mapper.select:
SELECT 
FROM user_resumes
WHERE user_id = #{userId}
  AND resume_id = #{resumeId}
LIMIT 1

SELECT COUNT(*)
FROM user_resumes
WHERE user_id = #{userId}

mapper.update:
UPDATE user_resumes
SET resume_name = #{resumeName},
    resume_data_json = CAST(#{resumeDataJson} AS JSON),
    updated_at = CURRENT_TIMESTAMP
WHERE user_id = #{userId}
  AND resume_id = #{resumeId}

UPDATE user_resumes
SET is_active = 1,
    updated_at = CURRENT_TIMESTAMP
WHERE user_id = #{userId}
  AND resume_id = #{resumeId}

mapper.delete:
DELETE FROM user_resumes
WHERE user_id = #{userId}
  AND resume_id = #{resumeId}
